(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.TLS_CORE=api})(typeof self!=='undefined'?self:this,function(){'use strict';
const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
function xpNeeded(level){return 100+50*level} function rankFor(level){return Math.min(10,Math.floor(level/10)+1)}
function addXP(s,amount){s.player.xp+=amount;let levels=0;while(s.player.level<100&&s.player.xp>=xpNeeded(s.player.level)){s.player.xp-=xpNeeded(s.player.level);s.player.level++;s.player.rank=rankFor(s.player.level);levels++}if(s.player.level===100)s.player.xp=0;return levels}
function usedCapacity(s,items){return Object.entries(s.inventory).reduce((n,[id,q])=>n+(items[id]?.weight||0)*q,0)}
function canAdd(s,id,qty,items){return usedCapacity(s,items)+(items[id]?.weight||0)*qty<=s.player.capacity+.001}
function addItem(s,id,qty,items){if(qty<=0||!canAdd(s,id,qty,items))return false;s.inventory[id]=(s.inventory[id]||0)+qty;return true}
function removeItems(s,cost){if(!Object.entries(cost).every(([id,q])=>(s.inventory[id]||0)>=q))return false;Object.entries(cost).forEach(([id,q])=>{s.inventory[id]-=q;if(s.inventory[id]<=0)delete s.inventory[id]});return true}
function purchase(s,entry,items){if(s.player.rank<entry.rank)return{ok:false,reason:'Rank locked'};if(s.player.credits<entry.price)return{ok:false,reason:'Not enough Credits'};if(!canAdd(s,entry.id,1,items))return{ok:false,reason:'Inventory full'};s.player.credits-=entry.price;addItem(s,entry.id,1,items);track(s,'purchase',1);return{ok:true}}
function craft(s,recipe,items){if(s.player.rank<recipe.rank)return{ok:false,reason:'Rank locked'};if(!Object.entries(recipe.cost).every(([id,q])=>(s.inventory[id]||0)>=q))return{ok:false,reason:'Missing materials'};let gain=Object.entries(recipe.makes);let released=Object.entries(recipe.cost).reduce((n,[id,q])=>n+(items[id]?.weight||0)*q,0),added=gain.reduce((n,[id,q])=>n+(items[id]?.weight||0)*q,0);if(usedCapacity(s,items)-released+added>s.player.capacity)return{ok:false,reason:'Inventory full'};removeItems(s,recipe.cost);gain.forEach(([id,q])=>addItem(s,id,q,items));s.world.minutes+=recipe.minutes;s.stats.energy=clamp(s.stats.energy-recipe.minutes*.08);track(s,'craft',1);return{ok:true}}
function track(s,type,amount=1){s.quests.forEach(q=>{if(q.claimed)return;q.objectives.forEach(o=>{if(o.type===type)o.current=Math.min(o.target,o.current+amount)})})}
function claimQuest(s,q){if(q.claimed||!q.objectives.every(o=>o.current>=o.target))return false;q.claimed=true;s.player.credits+=q.credits;addXP(s,q.xp);return true}
function applySurvival(s,dt){let m=dt/60;s.stats.hunger=clamp(s.stats.hunger-m*.11);s.stats.thirst=clamp(s.stats.thirst-m*.18);s.stats.energy=clamp(s.stats.energy-m*.08);if(s.stats.thirst<20)s.stats.energy=clamp(s.stats.energy-m*.22);if(s.stats.thirst<=0||s.stats.hunger<=0)s.stats.health=clamp(s.stats.health-m*.35);if(s.stats.energy<=3)s.stats.health=clamp(s.stats.health-m*.1)}
function freshState(quests){return{version:2,player:{name:'Darwin',level:1,xp:0,rank:1,credits:0,capacity:18,x:1000,y:640},stats:{health:100,energy:88,hunger:76,thirst:64,temperature:37},inventory:{},equipment:{},world:{day:1,minutes:390,weather:'Clear',weatherUntil:900},quests:quests.map(q=>({...q,claimed:false,objectives:q.objectives.map(o=>({type:o[0],target:o[1],label:o[2],current:0}))})),discovered:['clearing'],analysed:[],depleted:{},log:[],counters:{gathered:0,crafted:0,purchased:0},activeQuest:'awakening'}}
return{clamp,xpNeeded,rankFor,addXP,usedCapacity,canAdd,addItem,removeItems,purchase,craft,track,claimQuest,applySurvival,freshState};});
